svg.script:
var iframe = document.getElementById('game-frame');

function post(msg) {
  if (window.parent && window.parent !== window) {
    window.parent.postMessage(msg, '*');
  }
}

window.addEventListener('message', function (event) {
  var data = event.data;
  if (!data) return;

  try {
    if (data.type === 'URL' || data.url) {
      iframe.onload = function() { post({ type: 'content-loaded', source: 'launch-svg' }); };
      iframe.src = data.url;
      return;
    }

    if (data.type === 'CONTENT' && data.html) {
      iframe.onload = function() { post({ type: 'content-loaded', source: 'launch-svg' }); };
      iframe.srcdoc = data.html;
      return;
    }

    if (typeof data === 'string' && data.indexOf('CONTENT:') === 0) {
      iframe.onload = function() { post({ type: 'content-loaded', source: 'launch-svg' }); };
      iframe.srcdoc = data.slice(8);
    }
  } catch (e) {
    post({ type: 'content-error', source: 'launch-svg', error: e && e.message ? e.message : String(e) });
  }
});

post({ type: 'ready', source: 'launch-svg' });
